binary-tree-tilt:
class Solution:
    def findTilt(self, root: Optional[TreeNode]) -> int:
        self.total = 0
        def go(node):
            if not node:
                return 0
            l = go(node.left)
            r = go(node.right)
            self.total += abs(l - r)
            return l + r + node.val
        go(root)
        return self.total

