class NeighborSum:
    def __init__(self, grid: List[List[int]]):
        self.g = grid
        self.n = len(grid)
        self.pos = {}
        for i in range(self.n):
            for j in range(self.n):
                self.pos[self.g[i][j]] = (i, j)
    def adjacentSum(self, value: int) -> int:
        i, j = self.pos[value]
        return sum(self.g[i + a][j + b] for a, b in ((-1, 0), (1, 0), (0, -1), (0, 1)) if 0 <= i + a < self.n and 0 <= j + b < self.n)
    def diagonalSum(self, value: int) -> int:
        i, j = self.pos[value]
        return sum(self.g[i + a][j + b] for a, b in ((-1, -1), (-1, 1), (1, -1), (1, 1)) if 0 <= i + a < self.n and 0 <= j + b < self.n)

